def is_balanced(s: str) -> bool:
    stack = []
    pairs = {'(': ')', '[': ']', '{': '}'}
    for ch in s:
        if ch in pairs:
            stack.append(ch)
        elif ch in pairs.values():
            if not stack:
                return False
            open_char = stack.pop()
            if pairs[open_char] != ch:
                return False
    return len(stack) == 0
```

