def parse_duration(s: str) -> int:
    if not s:
        return 0
    total = 0
    i = 0
    n = len(s)
    while i < n:
        # Extract number
        j = i
        while j < n and s[j].isdigit():
            j += 1
        if j == i:
            # No digits found, skip
            i += 1
            continue
        num = int(s[i:j])
        if j < n:
            unit = s[j]
            if unit == 'h':
                total += num * 3600
            elif unit == 'm':
                total += num * 60
            elif unit == 's':
                total += num
            i = j + 1
        else:
            # No unit, treat as seconds? But spec says h, m, s in that order.
            # If no unit, assume seconds.
            total += num
            i = j
    return total
